function [ok] = inertia_realisable(j, s)
%INERTIA_REALISABLE  Whether principal moments j (the diagonal of the inertia) scaled by s are the moments of a body that can exist: each moment
%   positive and no one above the sum of the other two (a rigid body's I1 + I2 >= I3, for every ordering; equal to it is a flat plate).
%   A campaign's draw that breaks it is drawn again from the seed's stream; a stated inertia that breaks it is refused by name.
%   j: real[1][3][3] (passed a plain number)
%   s: real[1][3] (passed a plain number)
%   returns ok: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ok = false;
    a = (j(1, 1) * s(1));
    b = (j(2, 2) * s(2));
    c = (j(3, 3) * s(3));
    ok = ((((((a > 0) && (b > 0)) && (c > 0)) && ((a + b) >= c)) && ((b + c) >= a)) && ((a + c) >= b));
end
